import{_ as s,h as r,i,c as o,v as t,p as n,x as l,m as E,e as h,S as A}from"./chunks/framework.Dvtg8yj2.js";const _=JSON.parse('{"title":"Constitutional classifiers","description":"","frontmatter":{"title":"Constitutional classifiers","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/constitutional-classifiers.md","filePath":"llm/constitutional-classifiers.md","lastUpdated":1788454257000}'),p={name:"llm/constitutional-classifiers.md"};function c(d,a,m,u,f,B){const e=r("Mermaid");return i(),o("div",null,[a[1]||(a[1]=t('<h1 id="constitutional-classifiers" tabindex="-1">Constitutional classifiers <a class="header-anchor" href="#constitutional-classifiers" aria-label="Permalink to &quot;Constitutional classifiers&quot;">​</a></h1><div class="epigraph"><p>用自然语言宪法生成合成输入与标签，训练输入侧与输出侧分类器，使护栏的政策迭代不必每次重标几十万条对话，并能在普遍越狱压力下保持拒绝。</p><footer>—— Anthropic, Constitutional Classifiers, 2025</footer></div><p>Constitutional AI 用条款训练<strong>生成模型</strong>的偏好；Constitutional classifiers 把同一思想用在<strong>护栏</strong>上：人写一份宪法（允许什么、不允许什么、边界如何澄清），模型据此合成大量带标签的提示与回答，再训两个分类器，分别挡输入与输出。Anthropic 用它应对「普遍越狱」（universal jailbreak）——一条策略对许多危害请求同时奏效的情况——并公开了过拒绝与稳健性的权衡。本篇写合成监督、双分类器流水线、以及评测时该盯的泄漏与过拒绝；不提供宪法全文的可执行对照，不提供越狱策略。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>固定分类法加人工标注，迭代慢，见 <a href="/llm/llama-guard">Llama Guard</a>。政策每周改一条，标注队列跟不上，生产只能改提示，召回不稳。另一方面，只对齐生成模型挡不住<a href="/llm/gcg-suffix">GCG</a>、<a href="/llm/many-shot-jailbreak">many-shot</a>、<a href="/llm/prefill-jailbreak">预填充</a> 这类改变条件分布的输入；需要与生成模型解耦的门。宪法分类器要同时解决：政策用自然语言维护、数据用合成扩展、门与生成异构。</p><p>普遍越狱是评测目标里特别苛刻的一种：不是某一条危害行为被攻破，而是攻击者找到的策略在行为集合上<strong>平均</strong>成功。对产品而言，这意味着过滤器被一次性掀翻。防御声明必须在这种压力下测，而不是只测零散人工提示。</p><h3 id="合成标签的循环风险" tabindex="-1">合成标签的循环风险 <a class="header-anchor" href="#合成标签的循环风险" aria-label="Permalink to &quot;合成标签的循环风险&quot;">​</a></h3><p>用模型给模型打标签，错误会自增强：宪法若写得含糊，合成器会把含糊变成系统性偏见（某类合法医学内容被标有害，或某类隐蔽请求被标无害）。方法上必须有人类抽检、对抗集、以及与<a href="/llm/wildguard-harmbench">HarmBench</a> 类外部基准的对照。宪法分类器不是「不用人」，而是把人的劳动从逐条标注挪到写条款与审边界。</p><p><span class="marginnote">宪法写得越像律师条款，合成覆盖越好；写得越像口号，分类器越会过拒绝或只认关键词。条款要含允许的反例，而不仅仅是禁止清单。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流程是：写宪法 → 用强模型按条款生成提示、改写、回答与标签 → 过滤与人审抽样 → 训输入分类器与输出分类器 → 部署为生成模型前后的门 → 用红队与标准化基准做关闭环。输入分类器决定是否调用昂贵的生成；输出分类器决定是否把生成露给用户。两者都失败才构成一次对外泄漏。训练目标是普通分类或短序列生成，体积可以远小于对话模型，便于频繁重训。</p><p>与 Llama Guard 的差别主要在数据来源：Guard 依赖对话安全标注与固定 taxonomy；宪法路线用条款驱动合成，taxonomy 隐含在条款里，改条款即可再生数据。实践中可以混合：宪法合成补覆盖，真实对话补分布。评测上 Anthropic 强调在普遍越狱下的泄漏率，以及无害请求上的过拒绝率，两条必须同表。</p><h3 id="双门如何分担失败" tabindex="-1">双门如何分担失败 <a class="header-anchor" href="#双门如何分担失败" aria-label="Permalink to &quot;双门如何分担失败&quot;">​</a></h3><p>输入门对隐蔽改写、多轮指代、<a href="/llm/multimodal-jailbreak">多模态</a> 未覆盖通道会漏；输出门对已经生成的危害内容召回更高，但延迟与流式泄漏更差。输入门过严则伤害有用性且浪费不了多少算力（因为根本不生成）；输出门过严则用户看到长时间思考后被拒，体验更差。阈值应分开扫：输入偏召回还是偏精度，取决于 TTFT 预算与是否有廉价预检。宪法允许把「不确定则拒」写进输出门、把「不确定则放行并依赖输出门」写进输入门，这种不对称要在文档里写清。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是把政策从权重里的模糊方向，变成分类器输入空间里的显式决策面。合成数据的作用是在决策面附近铺密度：合法边界、改写、多种语言风格。分类器并不理解宪法的法哲学，它拟合的是合成器在条款条件下的标注行为。因此条款与合成器能力决定上限：合成器自己若可被越狱，生成的「有害样本」可能偏弱，分类器会对真实红队欠拟合。缓解是：合成阶段用多种策略与多种模型，并对合成失败（标成有害却无害、或反过来）做人审。</p><p>普遍越狱压力下，生成模型的拒答开场被掀翻，见 GCG 与 prefilling；分类器看到的是完整输入或完整输出，不依赖开场话术。这是相对生成模型对齐的几何优势。代价是：攻击者可以转而对着分类器优化，分类器必须自己做对抗训练或定期用新的合成攻击刷新。宪法分类器论文把这一点当作持续运营，而不是一次训练永远有效。</p><p><span class="marginnote">把同一宪法既用来训生成模型又用来训分类器，会共享盲区。异构基座、异构合成器，比「多一道同款门」更有用。</span></p><h3 id="防御评测协议" tabindex="-1">防御评测协议 <a class="header-anchor" href="#防御评测协议" aria-label="Permalink to &quot;防御评测协议&quot;">​</a></h3><p>最少三列：标准化基准成功率、针对普遍越狱的泄漏、无害集过拒绝。再加延迟与费用（每次请求几次分类器前向）。消融：只输入门、只输出门、双门、双门加生成模型自身对齐。对 many-shot，分类器上下文长度必须不小于产品窗口，或对窗口做分段投票并规定如何聚合。对预填充，输出分类器必须看见将要发出的完整助手文本，包括服务端允许的结构前缀。阈值扫描画帕累托曲线：泄漏 vs 过拒绝，避免只报曲线上最好看的一点。</p>',20)),(i(),n(A,null,{default:l(()=>[h(e,{id:"mermaid-58",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E8%87%AA%E7%84%B6%E8%AF%AD%E8%A8%80%E5%AE%AA%E6%B3%95%22%5D%20--%3E%20SYN%5B%22%E5%90%88%E6%88%90%E6%8F%90%E7%A4%BA%E4%B8%8E%E6%A0%87%E7%AD%BE%22%5D%0A%20%20HUM%5B%22%E4%BA%BA%E5%AE%A1%E6%8A%BD%E6%A0%B7%22%5D%20--%3E%20SYN%0A%20%20SYN%20--%3E%20IN%5B%22%E8%BE%93%E5%85%A5%E5%88%86%E7%B1%BB%E5%99%A8%22%5D%0A%20%20SYN%20--%3E%20OUT%5B%22%E8%BE%93%E5%87%BA%E5%88%86%E7%B1%BB%E5%99%A8%22%5D%0A%20%20REQ%5B%22%E7%94%A8%E6%88%B7%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20IN%0A%20%20IN%20--%3E%7C%22%E6%8B%A6%E6%88%AA%22%7C%20R1%5B%22%E5%AE%89%E5%85%A8%E5%9B%9E%E5%A4%8D%22%5D%0A%20%20IN%20--%3E%7C%22%E6%94%BE%E8%A1%8C%22%7C%20GEN%5B%22%E7%94%9F%E6%88%90%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20GEN%20--%3E%20OUT%0A%20%20OUT%20--%3E%7C%22%E6%8B%A6%E6%88%AA%22%7C%20R1%0A%20%20OUT%20--%3E%7C%22%E6%94%BE%E8%A1%8C%22%7C%20Y%5B%22%E5%AF%B9%E7%94%A8%E6%88%B7%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>合成数据填不满真实用户的长尾：新黑话、新工具 API、小语种。生产仍需要误报误漏的工单回流到宪法修订，而不是只加大合成温度。分类器对加密、编码、图像中文字的覆盖，取决于合成时是否显式包含这些通道；未写入宪法的通道等于未防御。过拒绝会集中在安全研究、新闻暴力、成人健康，条款必须有允许清单，评测集必须有对应子集。</p><p>与 Circuit Breaker、表示工程相比，宪法分类器不改生成模型内部，可热更新，适合政策频繁变的产品；但对白盒攻击者优化分类器输入仍然脆弱，需要与表示级打断叠用。本篇不给出宪法条目的可复制清单，以免变成绕过说明书；政策应在内部版本管理，对外只给用户级摘要。</p><p><span class="marginnote">「宪法」一词容易让人以为有形式化保证。它是一份自然语言规格加合成数据，保证强度不超过规格的清晰度与评测覆盖。没有证明，只有曲线。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Constitutional classifiers 用自然语言条款合成监督，训练与生成模型解耦的输入/输出分类器。</li><li>目标包括在普遍越狱压力下降低泄漏，同时用无害集约束过拒绝。</li><li>人的劳动在写条款与审边界，不在逐条标完所有对话。</li><li>双门分担漏检与延迟；阈值应分开扫并画帕累托曲线。</li><li>合成器与分类器会共享盲区，故需异构、需外部基准、需回流。</li><li>不改内部表示，热更新友好，但不能替代生成模型侧的鲁棒性工作。</li><li>出处：Anthropic, <em>Constitutional Classifiers</em>, 2025；思想衔接 Bai 等 Constitutional AI。</li></ul>',6))])}const b=s(p,[["render",c]]);export{_ as __pageData,b as default};
